import { Link } from "@/i18n/navigation";
import { usePathname } from "next/navigation";
import { useTranslations } from "next-intl";

const StatsNav: React.FC = () => {
  const t = useTranslations("ModernPages.stats");
  const pathname = usePathname() || "";
  const isDownload =
    pathname.includes("/stats/download") ||
    (!pathname.includes("/stats/trends") &&
      !pathname.includes("/stats/download"));
  const isTrends = pathname.includes("/stats/trends");
  return (
    <nav
      className="mx-auto max-w-7xl px-6 pt-6 sm:px-8"
      aria-label={t("subtitle")}
    >
      <div className="inline-flex flex-wrap gap-1 rounded-xl border border-white/10 bg-white/[0.025] p-1">
        <Link
          href="/stats/download"
          scroll={false}
          className={`rounded-lg px-4 py-2.5 text-sm font-medium focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink ${isDownload ? "bg-pink/15 text-[#ff91b7]" : "text-grey hover:bg-white/5 hover:text-white"}`}
          aria-current={isDownload ? "page" : undefined}
        >
          {t("downloads")}
        </Link>
        <Link
          href="/stats/trends"
          scroll={false}
          className={`rounded-lg px-4 py-2.5 text-sm font-medium focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-pink ${isTrends ? "bg-pink/15 text-[#ff91b7]" : "text-grey hover:bg-white/5 hover:text-white"}`}
          aria-current={isTrends ? "page" : undefined}
        >
          {t("trends")}
        </Link>
      </div>
    </nav>
  );
};

export default StatsNav;
